styles.css:
.wp-site-blocks > header{border-bottom:1px solid var(--wp--preset--color--accent-6);background:var(--wp--preset--color--base)}
.wp-block-navigation a:hover{color:var(--wp--preset--color--accent-1)}
.wp-block-button.is-style-outline>.wp-block-button__link{background:transparent;color:var(--wp--preset--color--accent-1);border:2px solid currentColor;padding-top:calc(.85rem - 2px);padding-bottom:calc(.85rem - 2px)}
.wp-block-button.is-style-outline>.wp-block-button__link:hover{background:var(--wp--preset--color--accent-5);color:var(--wp--preset--color--accent-3)}
a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--wp--preset--color--accent-2);outline-offset:2px}
.wp-block-details summary{font-family:var(--wp--preset--font-family--platypi);font-weight:600;font-size:1.25rem;cursor:pointer;list-style:none;display:flex;justify-content:space-between;gap:1rem}
.wp-block-details summary::-webkit-details-marker{display:none}
.wp-block-details summary::after{content:'+';color:var(--wp--preset--color--accent-1);font-size:1.5rem;line-height:1}
.wp-block-details[open] summary::after{content:'\2212'}
.wp-block-details>p{color:var(--wp--preset--color--accent-4);max-width:62ch}
.hm-precio{position:relative}
.hm-precio .hm-cifra{font-family:var(--wp--preset--font-family--platypi);font-weight:700;font-size:clamp(4.5rem,11vw,8.5rem);line-height:.9;letter-spacing:-.04em;margin:0}
.hm-precio .hm-cifra sup{font-size:.4em;vertical-align:.95em;margin-right:.05em;font-weight:600}
.hm-precio .hm-condiciones{font-family:var(--wp--preset--font-family--platypi);font-weight:500;font-size:clamp(1.5rem,2.6vw,2rem);line-height:1.15;letter-spacing:-.01em}
.hm-precio .hm-condiciones li{border-top:2px solid rgba(25,41,67,.28);padding:.5rem 0;list-style:none}
.hm-precio .hm-condiciones{padding:0;margin:0}
.hm-specs .hm-fila{border-top:1px solid var(--wp--preset--color--accent-6);padding:1rem 0;margin:0!important;align-items:baseline}
.hm-specs .hm-fila:last-child{border-bottom:1px solid var(--wp--preset--color--accent-6)}
.hm-specs .hm-valor{font-family:var(--wp--preset--font-family--platypi);font-weight:600;font-size:1.75rem;line-height:1.1;color:var(--wp--preset--color--accent-1);margin:0;min-width:7.5rem}
.hm-specs .hm-dato{margin:0}
.hm-razones .wp-block-column{border-top:3px solid var(--wp--preset--color--accent-2);padding-top:1.25rem}
.hm-razones p{color:var(--wp--preset--color--accent-4)}
.hm-pasos .hm-num{font-family:var(--wp--preset--font-family--platypi);font-weight:700;font-size:3rem;line-height:1;color:var(--wp--preset--color--accent-1);margin:0 0 .5rem}
.hm-pasos p{color:var(--wp--preset--color--accent-4)}
.hm-final h2,.hm-final p{color:var(--wp--preset--color--base)}
.hm-final .wp-block-button__link{background:var(--wp--preset--color--accent-2);color:var(--wp--preset--color--accent-3)}
.hm-final .wp-block-button__link:hover{background:#D2AD6E;color:var(--wp--preset--color--accent-3)}
.wc-block-checkout .wc-block-components-title,.wc-block-cart .wc-block-components-title{font-family:var(--wp--preset--font-family--platypi)}
.wc-block-components-button:not(.is-link){border-radius:10px}
@media (max-width:781px){.hm-specs .hm-fila{flex-wrap:nowrap!important}.hm-specs .hm-valor{min-width:6rem;font-size:1.4rem}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
html{scroll-behavior:smooth}
.wp-site-blocks > footer .wp-block-group > p.has-small-font-size{max-width:var(--wp--style--global--wide-size);color:var(--wp--preset--color--accent-4)}
.wp-site-blocks > footer{border-top:1px solid var(--wp--preset--color--accent-6)}
.wp-site-blocks > footer,.wp-site-blocks > main{margin-block-start:0}
.home .wp-site-blocks > main > .wp-block-post-content{margin-block-end:0}
.hm-pasos .hm-num{color:#9C773A}
::selection{background:var(--wp--preset--color--accent-2);color:var(--wp--preset--color--contrast)}
